#include <stdio.h>

// Extracted logic into a reusable, testable function
void print_multiplication_table(int base_number, int limit) {
    // Basic input validation (a must in production)
    if (limit < 0) {
        fprintf(stderr, "Error: Limit cannot be negative.\n");
        return;
    }

    for (int i = 0; i < limit; i++) {
        printf("%d x %d = %d\n", base_number, i, base_number * i);
    }
}

int main() {
    // Configuration at the top, variables declare intent
    const int TARGET_NUMBER = 7;
    const int MULTIPLIER_LIMIT = 5;

    // Function call makes main() clean and readable
    print_multiplication_table(TARGET_NUMBER, MULTIPLIER_LIMIT);

    return 0;
}

